.content h2 { font-size:20px;margin:28px 0 12px;color:#1a1a2e;padding-bottom:6px;border-bottom:2px solid #6C63FF }
.content h3 { font-size:17px;margin:20px 0 10px;color:#333 }
.content p { margin-bottom:14px;font-size:15px;color:#444 }
.content ul,.content ol { margin:10px 0 14px 20px }
.content li { margin-bottom:6px;font-size:15px;color:#444 }
.content strong { color:#1a1a2e }
.content blockquote { border-left:3px solid #6C63FF;margin:14px 0;padding:10px 16px;background:#f0eeff;border-radius:0 8px 8px 0;color:#555;font-size:14px }
.content table { width:100%;border-collapse:collapse;margin:14px 0;font-size:14px }
.content th,.content td { border:1px solid #ddd;padding:8px 12px;text-align:left }
.content th { background:#6C63FF;color:#fff;font-weight:600 }
.content tr:nth-child(even) { background:#f8f7ff }
.content hr { margin:24px 0;border:none;border-top:1px solid #eee }
